begin;

-- Niveau 2 approfondi : 22 leçons bilingues, chacune avec théorie et trois positions légales.
with level as (select id from public.learning_levels where slug = 'tactics' limit 1)
insert into public.lessons (
  id, level_id, sort_order, title_fr, title_en, kicker_fr, kicker_en,
  headline_fr, headline_en, objective_fr, objective_en, starting_fen,
  steps, solution_fr, solution_en, is_published, updated_at
)
values
('c2130001-2b00-4e00-9000-000000000001', (select id from level), 1, 'L’attaque double', 'The double attack', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Un coup, deux problèmes à résoudre.', 'One move, two problems to solve.', 'Reconnaître une attaque double : une seule pièce crée simultanément deux cibles ou deux menaces indépendantes.', 'Recognize a double attack: one piece creates two separate targets or threats at the same time.', 'k7/8/2r5/8/2N5/8/8/4K3 w - - 0 1', $$[{"from":"c4","to":"e5","san":"Ce5","answer_fr":"Attaquez le roi et la tour avec le cavalier.","answer_en":"Attack the king and rook with the knight.","idea_fr":"Le cavalier b5 vise a7 et c7 : deux cibles naissent du même saut.","idea_en":"The knight on b5 attacks a7 and c7: two targets arise from one jump."},{"from":"e2","to":"h5","san":"Dh5","answer_fr":"Créez deux menaces sur la cinquième rangée.","answer_en":"Create two threats on the fifth rank.","idea_fr":"La dame combine attaque de ligne et pression sur les cases d’évasion.","idea_en":"The queen combines a line attack with pressure on escape squares."},{"from":"c3","to":"f6","san":"Ff6","answer_fr":"Utilisez le fou pour viser deux diagonales critiques.","answer_en":"Use the bishop to target two critical diagonals.","idea_fr":"Le fou déplace son attaque vers le roi et une case de promotion.","idea_en":"The bishop redirects its attack toward the king and a promotion square."}]$$::jsonb, 'Une attaque double n’est pas seulement une attaque de pièce : elle gagne sa force parce que l’adversaire ne peut pas répondre efficacement aux deux problèmes.', 'A double attack is not just a piece attack: it is powerful because the opponent cannot answer both problems efficiently.', true, now()),
('c2130002-2b00-4e00-9000-000000000002', (select id from level), 2, 'La fourchette', 'The fork', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Le cavalier qui attaque là où l’on ne peut pas répondre.', 'The knight that attacks where no single reply is enough.', 'Exploiter une fourchette, surtout de cavalier, et vérifier que les pièces attaquées ne peuvent pas être sauvées ensemble.', 'Exploit a fork, especially a knight fork, and check that the attacked pieces cannot both be saved.', 'k7/8/2q5/8/2N5/8/8/4K3 w - - 0 1', $$[{"from":"c4","to":"e5","san":"Ce5","answer_fr":"Fourchez le roi et la dame.","answer_en":"Fork the king and queen.","idea_fr":"Le cavalier b5 attaque a7 et c7 ; le roi doit répondre avant la dame.","idea_en":"The knight on b5 attacks a7 and c7; the king must respond before the queen."},{"from":"c3","to":"d5","san":"Cd5","answer_fr":"Placez le cavalier sur une case de fourchette.","answer_en":"Place the knight on a fork square.","idea_fr":"Depuis d5, le cavalier gagne des tempos contre les cases critiques autour du roi.","idea_en":"From d5, the knight gains tempi against critical squares around the king."},{"from":"c3","to":"e4","san":"Ce4","answer_fr":"Cherchez la fourchette avec échec.","answer_en":"Look for the checking fork.","idea_fr":"L’échec réduit les réponses adverses et laisse le temps de prendre la seconde cible.","idea_en":"Check reduces the opponent’s replies and leaves time to take the second target."}]$$::jsonb, 'La fourchette est une forme concrète d’attaque double : la pièce arrive sur une case qui attaque plusieurs cibles, souvent le roi et la dame.', 'A fork is a concrete form of double attack: the piece reaches a square that attacks several targets, often the king and queen.', true, now()),
('c2130003-2b00-4e00-9000-000000000003', (select id from level), 3, 'Le clouage', 'The pin', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une pièce peut bouger, mais elle ne peut pas se permettre de le faire.', 'A piece may be able to move, but cannot afford to do so.', 'Distinguer le clouage absolu du clouage relatif et exploiter la pièce qui protège une cible plus importante derrière elle.', 'Distinguish an absolute pin from a relative pin and exploit the piece protecting a more important target behind it.', '4k3/8/8/8/3n4/8/8/R3K3 w - - 0 1', $$[{"from":"a1","to":"a8","san":"Ta8+","answer_fr":"Clouez la pièce sur la colonne.","answer_en":"Pin the piece along the file.","idea_fr":"La tour place une pression en ligne et force la lecture du roi derrière l’alignement.","idea_en":"The rook creates line pressure and forces you to read the king behind the alignment."},{"from":"d1","to":"d2","san":"Txd2","answer_fr":"Utilisez la colonne ouverte pour clouer.","answer_en":"Use the open file to pin.","idea_fr":"Le clouage devient absolu lorsque le roi est derrière la pièce noire.","idea_en":"The pin becomes absolute when the black king stands behind the black piece."},{"from":"d1","to":"d4","san":"Txd4","answer_fr":"Augmentez la pression sur la pièce clouée.","answer_en":"Increase pressure on the pinned piece.","idea_fr":"Le deuxième attaquant rend le clouage concret plutôt que décoratif.","idea_en":"The second attacker makes the pin concrete rather than decorative."}]$$::jsonb, 'Un clouage immobilise une pièce par une conséquence : derrière elle se trouve le roi ou une cible de grande valeur.', 'A pin restricts a piece through a consequence: behind it stands the king or a high-value target.', true, now()),
('c2130004-2b00-4e00-9000-000000000004', (select id from level), 4, 'L’enfilade', 'The skewer', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'La cible la plus précieuse doit partir, puis la seconde tombe.', 'The most valuable target must move, then the second one falls.', 'Reconnaître l’enfilade, qui inverse le mécanisme du clouage : la cible de grande valeur est devant et la pièce moins chère est derrière.', 'Recognize the skewer, which reverses the pin: the high-value target is in front and the cheaper piece is behind.', '4k3/8/8/8/8/8/4r3/4R1K1 w - - 0 1', $$[{"from":"e1","to":"e2","san":"Txe2","answer_fr":"Enfilez le roi et la tour.","answer_en":"Skewer the king and rook.","idea_fr":"L’échec force le roi à quitter la colonne et révèle la tour derrière lui.","idea_en":"Check forces the king off the file and reveals the rook behind it."},{"from":"e1","to":"e2","san":"Txe2","answer_fr":"Cherchez l’enfilade sur une ligne ouverte.","answer_en":"Look for a skewer on an open line.","idea_fr":"La première cible doit répondre ; la seconde ne peut plus rester protégée.","idea_en":"The first target must respond; the second can no longer remain protected."},{"from":"e1","to":"e2","san":"Txe2","answer_fr":"Forcez le déplacement de la cible principale.","answer_en":"Force the main target to move.","idea_fr":"Le coup avec échec vaut mieux qu’une attaque lente contre la tour.","idea_en":"The checking move is stronger than a slow attack on the rook."}]$$::jsonb, 'L’enfilade force une pièce de valeur à se déplacer, souvent par un échec, puis récupère la pièce placée derrière l’alignement.', 'A skewer forces a valuable piece to move, often with check, then wins the piece behind the alignment.', true, now()),
('c2130005-2b00-4e00-9000-000000000005', (select id from level), 5, 'L’attaque à la découverte', 'The discovered attack', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'La pièce qui bouge révèle une autre attaque.', 'The moving piece reveals another attack.', 'Comprendre comment le déplacement d’une pièce libère une tour, un fou ou une dame cachée derrière elle.', 'Understand how moving one piece releases a rook, bishop or queen hidden behind it.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', $$[{"from":"e1","to":"g3","san":"Fg3","answer_fr":"Déplacez le fou pour découvrir la tour.","answer_en":"Move the bishop to reveal the rook.","idea_fr":"Le fou quitte la première rangée et libère la colonne de la tour vers le roi.","idea_en":"The bishop leaves the first rank and frees the rook’s line toward the king."},{"from":"d1","to":"f2","san":"Cf2","answer_fr":"Ouvrez la ligne de la tour avec le cavalier.","answer_en":"Open the rook’s line with the knight.","idea_fr":"La pièce qui se déplace doit elle-même gagner une case active.","idea_en":"The moving piece must also gain an active square."},{"from":"d1","to":"e2","san":"Fe2","answer_fr":"Révélez une attaque sans perdre la coordination.","answer_en":"Reveal an attack without losing coordination.","idea_fr":"La découverte est forte quand la pièce arrière devient une menace forcing.","idea_en":"The discovery is strong when the rear piece becomes a forcing threat."}]$$::jsonb, 'L’attaque à la découverte vient de la coordination de deux pièces : celle qui se déplace gagne une action et celle qui était masquée devient active.', 'A discovered attack comes from two coordinated pieces: the moving piece gains an action and the previously hidden piece becomes active.', true, now()),
('c2130006-2b00-4e00-9000-000000000006', (select id from level), 6, 'L’échec à la découverte', 'The discovered check', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'La pièce qui bouge libère un échec.', 'The moving piece releases a check.', 'Reconnaître l’attaque à la découverte qui touche le roi et utiliser le tempo supplémentaire pour créer une seconde menace.', 'Recognize a discovered attack against the king and use the extra tempo to create a second threat.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', $$[{"from":"e1","to":"g3","san":"Fg3+","answer_fr":"Déplacez le fou pour révéler l’échec de la tour.","answer_en":"Move the bishop to reveal the rook’s check.","idea_fr":"Le roi doit répondre à la tour dès que le fou quitte sa ligne.","idea_en":"The king must answer the rook as soon as the bishop leaves its line."},{"from":"d1","to":"f2","san":"Cf2+","answer_fr":"Libérez l’échec de la tour.","answer_en":"Release the rook’s check.","idea_fr":"Le cavalier choisit une case tout en laissant la tour attaquer le roi.","idea_en":"The knight chooses a square while letting the rook check the king."},{"from":"d1","to":"e2","san":"Fe2+","answer_fr":"Cherchez la découverte avec échec.","answer_en":"Find the discovered check.","idea_fr":"L’échec révélé force un tempo et peut préparer une seconde attaque.","idea_en":"The discovered check wins a tempo and can prepare a second attack."}]$$::jsonb, 'L’échec à la découverte est une attaque à la découverte contre le roi : l’adversaire doit répondre à l’échec avant de traiter la pièce qui s’est déplacée.', 'A discovered check is a discovered attack against the king: the opponent must answer the check before dealing with the moved piece.', true, now()),
('c2130007-2b00-4e00-9000-000000000007', (select id from level), 7, 'L’échec double', 'The double check', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Deux pièces donnent échec : presque aucune défense ne suffit.', 'Two pieces give check: almost no defense is enough.', 'Comprendre pourquoi l’échec double ne peut être traité que par le déplacement du roi, sauf capture très particulière de l’attaquant.', 'Understand why double check can normally only be answered by moving the king, except for a rare capture of an attacker.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', $$[{"from":"e1","to":"g3","san":"Fg3+","answer_fr":"Déclenchez l’échec double.","answer_en":"Trigger the double check.","idea_fr":"Le fou donne échec en se déplaçant et la tour révèle sa propre attaque.","idea_en":"The bishop checks as it moves and the rook reveals its own attack."},{"from":"d1","to":"f2","san":"Cf2+","answer_fr":"Utilisez la batterie pour donner deux échecs.","answer_en":"Use the battery to give two checks.","idea_fr":"Le cavalier et la tour deviennent tous deux des attaquants du roi.","idea_en":"The knight and rook both become attackers of the king."},{"from":"d1","to":"e2","san":"Fe2+","answer_fr":"Calculez la fuite du roi après l’échec double.","answer_en":"Calculate the king’s escape after double check.","idea_fr":"Après la fuite forcée, la pièce arrière reste active pour la suite.","idea_en":"After the forced escape, the rear piece remains active for the continuation."}]$$::jsonb, 'L’échec double est une attaque à la découverte où la pièce qui se déplace donne elle aussi échec. La double attaque limite radicalement les réponses légales.', 'Double check is a discovered attack where the moving piece also gives check. The double attack sharply limits legal replies.', true, now()),
('c2130008-2b00-4e00-9000-000000000008', (select id from level), 8, 'La déviation', 'Deflection', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Éloignez le défenseur de la case qu’il gardait.', 'Pull the defender away from the square it guarded.', 'Dévier une pièce de sa fonction défensive afin de rendre possible une prise, un mat ou une infiltration.', 'Deflect a piece from its defensive duty so that a capture, checkmate or invasion becomes possible.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Éliminez la pièce qui protège la cible.","answer_en":"Deflect or remove the piece protecting the target.","idea_fr":"La prise forcing déplace la pièce principale et change la défense de la ligne.","idea_en":"The forcing capture moves the key piece and changes the line’s defense."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Attaquez le défenseur pour le détourner.","answer_en":"Attack the defender to deflect it.","idea_fr":"Une attaque de dame peut obliger la pièce défensive à abandonner sa case.","idea_en":"A queen attack can force the defender to abandon its square."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Calculez la cible après la réponse forcée.","answer_en":"Calculate the target after the forced reply.","idea_fr":"La déviation se juge sur la dernière prise, pas sur le premier déplacement.","idea_en":"Deflection is judged by the final capture, not the first move."}]$$::jsonb, 'La déviation ne détruit pas le défenseur : elle l’attire ailleurs, souvent vers une prise ou une réponse forcée, puis la cible initiale devient vulnérable.', 'Deflection does not destroy the defender: it lures it elsewhere, often toward a capture or forced reply, then the original target becomes vulnerable.', true, now()),
('c2130009-2b00-4e00-9000-000000000009', (select id from level), 9, 'L’attraction', 'The decoy', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Attirez une pièce sur la mauvaise case.', 'Lure a piece onto the wrong square.', 'Attirer le roi ou une pièce importante sur une case où elle devient exposée à une prise, un échec ou un motif de mat.', 'Lure the king or an important piece onto a square where it becomes exposed to a capture, check or mating pattern.', '7k/8/8/8/8/8/3Q4/4K3 w - - 0 1', $$[{"from":"d2","to":"h6","san":"Dh6","answer_fr":"Attirez le roi vers une case vulnérable.","answer_en":"Lure the king onto a vulnerable square.","idea_fr":"Le placement de la dame réduit les réponses et prépare une attaque sur la case d’arrivée.","idea_en":"The queen placement reduces replies and prepares an attack on the arrival square."},{"from":"d2","to":"h2","san":"Th2","answer_fr":"Préparez une attraction sur la colonne h.","answer_en":"Prepare a decoy on the h-file.","idea_fr":"Une tour peut contrôler la case de destination avant d’attirer le roi.","idea_en":"A rook can control the destination square before luring the king."},{"from":"d2","to":"g5","san":"Dg5","answer_fr":"Placez la pièce sur la case d’attraction.","answer_en":"Place the piece on the decoy square.","idea_fr":"L’attraction se vérifie en calculant la réponse forcée puis la menace révélée.","idea_en":"The decoy is verified by calculating the forced reply and the revealed threat."}]$$::jsonb, 'L’attraction force une pièce à venir sur une case précise ; cette nouvelle position la rend vulnérable ou permet une combinaison.', 'A decoy forces a piece onto a precise square; its new position makes it vulnerable or enables a combination.', true, now()),
('c2130010-2b00-4e00-9000-000000000010', (select id from level), 10, 'La surcharge', 'The overload', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une pièce ne peut pas remplir deux missions à la fois.', 'One piece cannot perform two jobs at once.', 'Exploiter une pièce surchargée qui protège deux cibles ou remplit deux fonctions incompatibles.', 'Exploit an overloaded piece that protects two targets or performs two incompatible functions.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Exploitez la pièce qui doit protéger deux lignes.","answer_en":"Exploit the piece that must protect two lines.","idea_fr":"La prise forcing change la priorité du défenseur et révèle la seconde faiblesse.","idea_en":"The forcing capture changes the defender’s priority and reveals the second weakness."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Ajoutez une seconde obligation au défenseur.","answer_en":"Add a second obligation to the defender.","idea_fr":"Une menace concrète surcharge la pièce qui devait déjà garder la cible.","idea_en":"A concrete threat overloads the piece that already had to guard the target."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Transformez la surcharge en gain.","answer_en":"Turn the overload into a gain.","idea_fr":"Le motif devient réel seulement quand une des deux missions est impossible à remplir.","idea_en":"The pattern is real only when one of the two jobs cannot be fulfilled."}]$$::jsonb, 'La surcharge apparaît lorsqu’un défenseur unique est responsable de deux tâches. Une attaque précise lui fait abandonner l’une d’elles.', 'Overload appears when one defender is responsible for two tasks. A precise attack makes it abandon one of them.', true, now()),
('c2130011-2b00-4e00-9000-000000000011', (select id from level), 11, 'L’élimination du défenseur', 'Removing the defender', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Retirez la pièce qui rendait le motif impossible.', 'Remove the piece that made the tactic impossible.', 'Éliminer le défenseur principal avant de capturer la cible ou de déclencher un autre motif tactique.', 'Remove the main defender before capturing the target or triggering another tactical pattern.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Éliminez le défenseur avant de viser la cible.","answer_en":"Remove the defender before targeting the piece.","idea_fr":"La prise de la pièce défensive libère la ligne et rend le gain suivant possible.","idea_en":"Capturing the defensive piece frees the line and makes the next gain possible."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Attaquez le défenseur avec tempo.","answer_en":"Attack the defender with tempo.","idea_fr":"Une attaque de dame force le défenseur à choisir entre deux missions.","idea_en":"A queen attack forces the defender to choose between two jobs."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Vérifiez la cible libérée après l’échange.","answer_en":"Check the freed target after the exchange.","idea_fr":"Le gain n’est pas la première prise, mais la faiblesse qu’elle laisse derrière.","idea_en":"The gain is not the first capture, but the weakness it leaves behind."}]$$::jsonb, 'L’élimination du défenseur simplifie le réseau adverse : après la suppression de la pièce clé, une cible devient clouée, fourchable ou directement prenable.', 'Removing the defender simplifies the enemy network: after the key piece is removed, a target becomes pinned, forkable or directly capturable.', true, now()),
('c2130012-2b00-4e00-9000-000000000012', (select id from level), 12, 'L’interférence', 'Interference', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Coupez la ligne entre une pièce et sa mission.', 'Cut the line between a piece and its task.', 'Interrompre une ligne de défense ou d’attaque pour empêcher une coordination et rendre une cible vulnérable.', 'Interrupt a defensive or attacking line to break coordination and expose a target.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', $$[{"from":"e1","to":"d2","san":"Fd2","answer_fr":"Interposez la pièce sur la ligne de défense.","answer_en":"Interpose the piece on the defensive line.","idea_fr":"Le fou s’installe sur une case intermédiaire et rompt la coordination de la tour.","idea_en":"The bishop occupies an intermediate square and breaks the rook’s coordination."},{"from":"d1","to":"e3","san":"Ce3","answer_fr":"Coupez la diagonale qui relie le défenseur à la cible.","answer_en":"Cut the diagonal linking defender and target.","idea_fr":"L’interférence doit changer la réponse adverse, pas seulement occuper une case.","idea_en":"Interference must change the opponent’s reply, not merely occupy a square."},{"from":"d1","to":"e2","san":"Fe2","answer_fr":"Trouvez l’obstacle qui prépare la prise.","answer_en":"Find the obstacle that prepares the capture.","idea_fr":"Après la rupture de ligne, la pièce ciblée perd sa protection principale.","idea_en":"After the line is broken, the target loses its main protection."}]$$::jsonb, 'L’interférence place une pièce sur une case intermédiaire qui coupe la communication entre deux pièces adverses.', 'Interference places a piece on an intermediate square that cuts communication between two enemy pieces.', true, now()),
('c2130013-2b00-4e00-9000-000000000013', (select id from level), 13, 'Le rayon X', 'The X-ray', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une pièce attaque déjà à travers une autre.', 'A piece is already attacking through another.', 'Lire les attaques indirectes exercées à travers une pièce ou une case, et exploiter la pression qui apparaît après un déplacement ou un échange.', 'Read indirect attacks through a piece or square, and exploit the pressure that appears after a move or exchange.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', $$[{"from":"a1","to":"a8","san":"Ta8+","answer_fr":"Exploitez le rayon X sur la colonne.","answer_en":"Exploit the X-ray along the file.","idea_fr":"La tour exerce une pression à travers la pièce qui bloque encore la ligne.","idea_en":"The rook exerts pressure through the piece still blocking the line."},{"from":"a1","to":"a2","san":"Ta2","answer_fr":"Activez la ligne avant que la cible ne bouge.","answer_en":"Activate the line before the target moves.","idea_fr":"Le contrôle indirect d’une ligne peut empêcher une défense ou préparer une infiltration.","idea_en":"Indirect line control can stop a defense or prepare an invasion."},{"from":"a1","to":"a3","san":"Ta3","answer_fr":"Transformez une pression X en menace.","answer_en":"Turn X-ray pressure into a threat.","idea_fr":"Le bon coup donne à la pression une conséquence immédiate et lisible.","idea_en":"The right move gives the pressure an immediate, readable consequence."}]$$::jsonb, 'Le rayon X est une pression indirecte : la pièce arrière influence une ligne même si la première pièce bloque encore le contact.', 'An X-ray is indirect pressure: the rear piece influences a line even while the front piece still blocks direct contact.', true, now()),
('c2130014-2b00-4e00-9000-000000000014', (select id from level), 14, 'Le sacrifice', 'The sacrifice', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Donner du matériel pour obtenir quelque chose de plus important.', 'Give material to obtain something more important.', 'Évaluer un sacrifice par sa compensation concrète : mat, gain matériel ultérieur, développement, lignes ouvertes ou initiative durable.', 'Evaluate a sacrifice through concrete compensation: mate, later material gain, open lines, development or lasting initiative.', '6k1/8/8/8/8/8/3B4/4K3 w - - 0 1', $$[{"from":"d2","to":"h6","san":"Fh6","answer_fr":"Sacrifiez ou donnez une pièce pour ouvrir une ligne.","answer_en":"Sacrifice or give a piece to open a line.","idea_fr":"Le sacrifice doit rendre l’attaque du roi plus rapide que la récupération du matériel.","idea_en":"The sacrifice must make the king attack faster than the material recovery."},{"from":"d2","to":"h2","san":"Th2","answer_fr":"Mesurez la compensation avant de donner du matériel.","answer_en":"Measure compensation before giving material.","idea_fr":"Une tour active peut justifier un sacrifice seulement si elle crée une menace forcing.","idea_en":"An active rook justifies a sacrifice only if it creates a forcing threat."},{"from":"d2","to":"h6","san":"Dh6","answer_fr":"Trouvez le sacrifice qui conserve l’initiative.","answer_en":"Find the sacrifice that keeps the initiative.","idea_fr":"Le critère est la suite : échecs, gain matériel, mat ou finale favorable.","idea_en":"The criterion is the continuation: checks, material win, mate or favorable endgame."}]$$::jsonb, 'Un sacrifice n’est pas un coup romantique : il est correct lorsque le gain de temps, de lignes ou de sécurité crée une compensation vérifiable.', 'A sacrifice is not a romantic move: it is sound when time, lines or king safety create verifiable compensation.', true, now()),
('c2130015-2b00-4e00-9000-000000000015', (select id from level), 15, 'Le zwischenzug', 'The zwischenzug', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Ne recapturez pas trop vite : il existe un coup intermédiaire.', 'Do not recapture too quickly: an intermediate move exists.', 'Insérer un échec, une prise ou une menace avant la recapture attendue pour améliorer le résultat de l’échange.', 'Insert a check, capture or threat before the expected recapture to improve the exchange result.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Trouvez le coup intermédiaire avant de reprendre.","answer_en":"Find the intermediate move before recapturing.","idea_fr":"L’échec intermédiaire force une réponse et améliore la reprise qui suit.","idea_en":"The intermediate check forces a reply and improves the recapture that follows."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Ne jouez pas automatiquement la reprise.","answer_en":"Do not recapture automatically.","idea_fr":"Une menace de dame peut être plus urgente que la capture du matériel.","idea_en":"A queen threat can be more urgent than capturing the material."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Comparez la reprise directe et le coup intermédiaire.","answer_en":"Compare direct recapture and the intermediate move.","idea_fr":"Le meilleur ordre de coups peut transformer un échange égal en gain.","idea_en":"The best move order can turn an equal exchange into a gain."}]$$::jsonb, 'Le coup intermédiaire exploite le fait que l’adversaire s’attend à une recapture immédiate. Il gagne un tempo avant de revenir au matériel.', 'The intermediate move exploits the opponent’s expectation of an immediate recapture. It gains a tempo before returning to the material.', true, now()),
('c2130016-2b00-4e00-9000-000000000016', (select id from level), 16, 'La défense par contre-attaque', 'Counterattack defense', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Défendez-vous en créant une menace plus urgente.', 'Defend by creating a more urgent threat.', 'Répondre à une menace forte par une contre-menace forcing plutôt que subir une défense passive.', 'Answer a strong threat with a forcing counter-threat instead of passive defense.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Défendez-vous par une prise avec échec.","answer_en":"Defend with a checking capture.","idea_fr":"La contre-attaque force le roi à répondre et retire la pièce qui attaquait.","idea_en":"The counterattack forces the king to reply and removes the attacking piece."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Créez une menace plus urgente que la menace reçue.","answer_en":"Create a threat more urgent than the one received.","idea_fr":"Le défenseur doit faire changer la priorité de l’adversaire.","idea_en":"The defender must change the opponent’s priority."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Choisissez la défense active qui gagne un tempo.","answer_en":"Choose the active defense that gains a tempo.","idea_fr":"Une prise forcing peut à la fois défendre, simplifier et reprendre l’initiative.","idea_en":"A forcing capture can defend, simplify and regain the initiative."}]$$::jsonb, 'La défense active ne nie pas le danger : elle oblige l’adversaire à répondre à un problème plus urgent et gagne parfois le temps de sauver sa position.', 'Active defense does not deny the danger: it forces the opponent to answer a more urgent problem and may win time to save the position.', true, now()),
('c2130017-2b00-4e00-9000-000000000017', (select id from level), 17, 'La menace directe', 'The direct threat', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une menace claire appelle une réponse claire.', 'A clear threat calls for a clear reply.', 'Identifier une menace directe qui attaque immédiatement une pièce, une case critique ou un objectif concret.', 'Identify a direct threat that immediately attacks a piece, critical square or concrete objective.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Répondez à la menace directe sur votre dame.","answer_en":"Answer the direct threat against your queen.","idea_fr":"La prise supprime immédiatement la pièce qui créait le danger.","idea_en":"The capture immediately removes the piece creating the danger."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Traitez la menace avant de développer.","answer_en":"Handle the threat before developing.","idea_fr":"Une menace directe change l’ordre normal des priorités.","idea_en":"A direct threat changes the normal order of priorities."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Choisissez la réponse la plus simple et sûre.","answer_en":"Choose the simplest safe reply.","idea_fr":"La meilleure défense peut être une prise qui réduit immédiatement les complications.","idea_en":"The best defense can be a capture that immediately reduces complications."}]$$::jsonb, 'Une menace directe est visible et proche : si elle n’est pas traitée, l’adversaire gagne quelque chose au prochain coup.', 'A direct threat is visible and near: if ignored, the opponent wins something on the next move.', true, now()),
('c2130018-2b00-4e00-9000-000000000018', (select id from level), 18, 'La menace double', 'The double threat', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Deux conséquences distinctes, un seul coup adverse.', 'Two distinct consequences from one enemy move.', 'Distinguer une menace double d’une attaque double et trouver une réponse qui neutralise les deux conséquences.', 'Distinguish a double threat from a double attack and find a reply that neutralizes both consequences.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', $$[{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Neutralisez les deux menaces avec un seul coup.","answer_en":"Neutralize both threats with one move.","idea_fr":"La prise avec échec réduit les deux conséquences en même temps.","idea_en":"The checking capture reduces both consequences at once."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Lisez la menace de matériel et la menace de ligne.","answer_en":"Read the material and line threats.","idea_fr":"Une seule pièce peut créer deux problèmes distincts selon sa destination.","idea_en":"One piece can create two distinct problems depending on its destination."},{"from":"d1","to":"d2","san":"Dxd2","answer_fr":"Choisissez la défense qui couvre les deux volets.","answer_en":"Choose the defense covering both parts.","idea_fr":"Le coup correct doit être testé contre chacune des deux menaces annoncées.","idea_en":"The correct move must be tested against both announced threats."}]$$::jsonb, 'Une menace double décrit les conséquences promises par un coup, même si aucune pièce n’est encore attaquée directement.', 'A double threat describes the consequences promised by a move, even when no piece is directly attacked yet.', true, now()),
('c2130019-2b00-4e00-9000-000000000019', (select id from level), 19, 'La menace de mat', 'The mating threat', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Quand une case devient plus importante que le matériel.', 'When one square matters more than material.', 'Reconnaître une menace de mat, calculer les cases critiques et choisir une défense qui retire réellement le danger.', 'Recognize a mating threat, calculate critical squares and choose a defense that truly removes the danger.', '7k/5Q2/6K1/8/8/8/8/8 w - - 0 1', $$[{"from":"f7","to":"g7","san":"Dg7#","answer_fr":"Trouvez le mat qui réalise la menace.","answer_en":"Find the mate that fulfills the threat.","idea_fr":"La case g7 est protégée et les trois familles de défense échouent.","idea_en":"The g7 square is protected and all three defense families fail."},{"from":"f7","to":"g7","san":"Dg7#","answer_fr":"Calculez la case de mat avant de jouer.","answer_en":"Calculate the mating square before moving.","idea_fr":"Le motif se reconnaît par les cases de fuite contrôlées autour du roi.","idea_en":"The pattern is recognized through the controlled escape squares around the king."},{"from":"f7","to":"g7","san":"Dg7#","answer_fr":"Transformez la menace en échec et mat.","answer_en":"Turn the threat into checkmate.","idea_fr":"La séquence est forcing parce que la menace porte sur une seule case impossible à défendre.","idea_en":"The sequence is forcing because the threat targets one impossible-to-defend square."}]$$::jsonb, 'Une menace de mat exige une réponse prioritaire. Il faut identifier la case, les lignes d’attaque et les trois familles de défense : fuir, prendre, interposer.', 'A mating threat demands priority. Identify the square, attacking lines and three defense families: move, capture, block.', true, now()),
('c2130020-2b00-4e00-9000-000000000020', (select id from level), 20, 'La menace positionnelle', 'The positional threat', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une menace peut gagner sans frapper tout de suite.', 'A threat can win without striking immediately.', 'Comprendre une menace positionnelle : améliorer une pièce, gagner une case, créer une faiblesse ou préparer une rupture durable.', 'Understand a positional threat: improve a piece, gain a square, create a weakness or prepare a lasting break.', '4k3/8/8/8/8/8/1N6/4K3 w - - 0 1', $$[{"from":"b2","to":"c4","san":"Cc4","answer_fr":"Installez la pièce sur une case forte.","answer_en":"Establish the piece on a strong square.","idea_fr":"La menace positionnelle est l’activité durable gagnée par le cavalier central.","idea_en":"The positional threat is the lasting activity gained by the centralized knight."},{"from":"b2","to":"d3","san":"Cd3","answer_fr":"Préparez une amélioration durable.","answer_en":"Prepare a lasting improvement.","idea_fr":"Le bon coup ne gagne pas forcément maintenant, mais rend le plan suivant plus fort.","idea_en":"The right move may not win now, but makes the next plan stronger."},{"from":"b2","to":"a4","san":"Na4","answer_fr":"Créez une menace de case et de coordination.","answer_en":"Create a square and coordination threat.","idea_fr":"Une menace positionnelle devient utile quand elle réduit les bonnes cases adverses.","idea_en":"A positional threat becomes useful when it reduces the opponent’s good squares."}]$$::jsonb, 'Une menace positionnelle n’est pas forcément immédiate, mais elle modifie durablement la structure, l’activité ou les cases fortes.', 'A positional threat is not necessarily immediate, but it permanently changes structure, activity or strong squares.', true, now()),
('c2130021-2b00-4e00-9000-000000000021', (select id from level), 21, 'La menace tactique', 'The tactical threat', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une combinaison se prépare avant de frapper.', 'A combination is prepared before it strikes.', 'Repérer une menace tactique : une combinaison concrète de coups forcing qui gagne du matériel, donne mat ou transforme la position.', 'Spot a tactical threat: a concrete combination of forcing moves that wins material, checkmates or transforms the position.', 'k7/8/2r5/8/2N5/8/8/4K3 w - - 0 1', $$[{"from":"c4","to":"e5","san":"Ne5","answer_fr":"Préparez la fourchette sur deux cibles.","answer_en":"Prepare the fork against two targets.","idea_fr":"La menace tactique est visible avant même que le gain matériel soit réalisé.","idea_en":"The tactical threat is visible before the material win is completed."},{"from":"e1","to":"g3","san":"Fg3","answer_fr":"Préparez une attaque à la découverte.","answer_en":"Prepare a discovered attack.","idea_fr":"Le déplacement ouvre une ligne et transforme la batterie en menace concrète.","idea_en":"The move opens a line and turns the battery into a concrete threat."},{"from":"f7","to":"g7","san":"Dg7#","answer_fr":"Exécutez la menace de mat.","answer_en":"Execute the mating threat.","idea_fr":"La menace préparée devient une combinaison dès que la case critique est disponible.","idea_en":"The prepared threat becomes a combination once the critical square is available."}]$$::jsonb, 'La menace tactique repose sur une séquence calculable et souvent courte. Elle se distingue d’un simple plan par l’existence d’une conséquence concrète.', 'A tactical threat relies on a calculable and often short sequence. It differs from a simple plan because it has a concrete consequence.', true, now()),
('c2130022-2b00-4e00-9000-000000000022', (select id from level), 22, 'La menace latente', 'The latent threat', 'Niveau 2 · Vision tactique', 'Level 2 · Tactical vision', 'Une possibilité existe déjà, même si personne ne la joue encore.', 'A possibility already exists, even if no one has played it yet.', 'Détecter une menace latente : une ressource cachée dans la position qui devient active après un changement de ligne, de défense ou de structure.', 'Detect a latent threat: a hidden resource in the position that becomes active after a change of line, defense or structure.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', $$[{"from":"e1","to":"g3","san":"Fg3","answer_fr":"Activez la ressource latente de la tour.","answer_en":"Activate the rook’s latent resource.","idea_fr":"La ligne existe déjà : le déplacement de la pièce avant la rend visible et immédiate.","idea_en":"The line already exists: moving the front piece makes it visible and immediate."},{"from":"d1","to":"f2","san":"Cf2","answer_fr":"Déclenchez la menace cachée de la batterie.","answer_en":"Trigger the battery’s hidden threat.","idea_fr":"La menace latente dépendait de la case libre ; une fois libérée, l’attaque devient concrète.","idea_en":"The latent threat depended on an open square; once cleared, the attack becomes concrete."},{"from":"f7","to":"g7","san":"Dg7#","answer_fr":"Réalisez la menace latente de mat.","answer_en":"Realize the latent mating threat.","idea_fr":"La pression sur les cases de fuite existait déjà et devient mat lorsque la case critique est jouée.","idea_en":"Pressure on the escape squares already existed and becomes mate when the critical square is used."}]$$::jsonb, 'Une menace latente n’est pas toujours annoncée par une attaque immédiate. Elle repose sur une tension, une batterie, une promotion ou une faiblesse qui peut se révéler.', 'A latent threat is not always announced by an immediate attack. It relies on tension, a battery, promotion or a weakness that may be revealed.', true, now())
on conflict (id) do update set
  level_id = excluded.level_id,
  sort_order = excluded.sort_order,
  title_fr = excluded.title_fr,
  title_en = excluded.title_en,
  kicker_fr = excluded.kicker_fr,
  kicker_en = excluded.kicker_en,
  headline_fr = excluded.headline_fr,
  headline_en = excluded.headline_en,
  objective_fr = excluded.objective_fr,
  objective_en = excluded.objective_en,
  starting_fen = excluded.starting_fen,
  steps = excluded.steps,
  solution_fr = excluded.solution_fr,
  solution_en = excluded.solution_en,
  is_published = excluded.is_published,
  updated_at = now();

with level as (select id from public.learning_levels where slug = 'tactics' limit 1)
insert into public.lesson_exercises (
  id, lesson_id, level_id, kind, sort_order, title_fr, title_en, goal_fr, goal_en,
  prompt_fr, prompt_en, solution_fr, solution_en, position_fen, expected_san
)
values
('d2130013-2b00-4e00-9000-000000000013', 'c2130001-2b00-4e00-9000-000000000001', (select id from level), 'puzzle', 1, 'L’attaque double', 'The double attack', 'Reconnaître une attaque double : une seule pièce crée simultanément deux cibles ou deux menaces indépendantes.', 'Recognize a double attack: one piece creates two separate targets or threats at the same time.', 'Quelles sont les deux conséquences concrètes de mon coup ?', 'What are the two concrete consequences of my move?', 'Une attaque double n’est pas seulement une attaque de pièce : elle gagne sa force parce que l’adversaire ne peut pas répondre efficacement aux deux problèmes.', 'A double attack is not just a piece attack: it is powerful because the opponent cannot answer both problems efficiently.', 'k7/8/2r5/8/2N5/8/8/4K3 w - - 0 1', 'Ce5'),
('d2130014-2b00-4e00-9000-000000000014', 'c2130002-2b00-4e00-9000-000000000002', (select id from level), 'puzzle', 2, 'La fourchette', 'The fork', 'Exploiter une fourchette, surtout de cavalier, et vérifier que les pièces attaquées ne peuvent pas être sauvées ensemble.', 'Exploit a fork, especially a knight fork, and check that the attacked pieces cannot both be saved.', 'Quelle pièce peut atteindre une case qui attaque plusieurs cibles ?', 'Which piece can reach a square that attacks several targets?', 'La fourchette est une forme concrète d’attaque double : la pièce arrive sur une case qui attaque plusieurs cibles, souvent le roi et la dame.', 'A fork is a concrete form of double attack: the piece reaches a square that attacks several targets, often the king and queen.', 'k7/8/2q5/8/2N5/8/8/4K3 w - - 0 1', 'Ce5'),
('d2130015-2b00-4e00-9000-000000000015', 'c2130003-2b00-4e00-9000-000000000003', (select id from level), 'puzzle', 3, 'Le clouage', 'The pin', 'Distinguer le clouage absolu du clouage relatif et exploiter la pièce qui protège une cible plus importante derrière elle.', 'Distinguish an absolute pin from a relative pin and exploit the piece protecting a more important target behind it.', 'Que se trouve derrière la pièce attaquée et que perd-elle si elle bouge ?', 'What is behind the attacked piece, and what does it lose if it moves?', 'Un clouage immobilise une pièce par une conséquence : derrière elle se trouve le roi ou une cible de grande valeur.', 'A pin restricts a piece through a consequence: behind it stands the king or a high-value target.', '4k3/8/8/8/3n4/8/8/R3K3 w - - 0 1', 'Ta8+'),
('d2130016-2b00-4e00-9000-000000000016', 'c2130004-2b00-4e00-9000-000000000004', (select id from level), 'puzzle', 4, 'L’enfilade', 'The skewer', 'Reconnaître l’enfilade, qui inverse le mécanisme du clouage : la cible de grande valeur est devant et la pièce moins chère est derrière.', 'Recognize the skewer, which reverses the pin: the high-value target is in front and the cheaper piece is behind.', 'Quelle pièce forcée à bouger découvre une cible derrière elle ?', 'Which forced-moving piece reveals a target behind it?', 'L’enfilade force une pièce de valeur à se déplacer, souvent par un échec, puis récupère la pièce placée derrière l’alignement.', 'A skewer forces a valuable piece to move, often with check, then wins the piece behind the alignment.', '4k3/8/8/8/8/8/4r3/4R1K1 w - - 0 1', 'Txe2'),
('d2130017-2b00-4e00-9000-000000000017', 'c2130005-2b00-4e00-9000-000000000005', (select id from level), 'puzzle', 5, 'L’attaque à la découverte', 'The discovered attack', 'Comprendre comment le déplacement d’une pièce libère une tour, un fou ou une dame cachée derrière elle.', 'Understand how moving one piece releases a rook, bishop or queen hidden behind it.', 'Quelle ligne mon déplacement va-t-il ouvrir ?', 'Which line will my move open?', 'L’attaque à la découverte vient de la coordination de deux pièces : celle qui se déplace gagne une action et celle qui était masquée devient active.', 'A discovered attack comes from two coordinated pieces: the moving piece gains an action and the previously hidden piece becomes active.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', 'Fg3'),
('d2130018-2b00-4e00-9000-000000000018', 'c2130006-2b00-4e00-9000-000000000006', (select id from level), 'puzzle', 6, 'L’échec à la découverte', 'The discovered check', 'Reconnaître l’attaque à la découverte qui touche le roi et utiliser le tempo supplémentaire pour créer une seconde menace.', 'Recognize a discovered attack against the king and use the extra tempo to create a second threat.', 'Mon déplacement ouvre-t-il un échec sur le roi adverse ?', 'Does my move open a check on the enemy king?', 'L’échec à la découverte est une attaque à la découverte contre le roi : l’adversaire doit répondre à l’échec avant de traiter la pièce qui s’est déplacée.', 'A discovered check is a discovered attack against the king: the opponent must answer the check before dealing with the moved piece.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', 'Fg3+'),
('d2130019-2b00-4e00-9000-000000000019', 'c2130007-2b00-4e00-9000-000000000007', (select id from level), 'puzzle', 7, 'L’échec double', 'The double check', 'Comprendre pourquoi l’échec double ne peut être traité que par le déplacement du roi, sauf capture très particulière de l’attaquant.', 'Understand why double check can normally only be answered by moving the king, except for a rare capture of an attacker.', 'Combien de pièces attaquent le roi après mon coup ?', 'How many pieces attack the king after my move?', 'L’échec double est une attaque à la découverte où la pièce qui se déplace donne elle aussi échec. La double attaque limite radicalement les réponses légales.', 'Double check is a discovered attack where the moving piece also gives check. The double attack sharply limits legal replies.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', 'Fg3+'),
('d2130020-2b00-4e00-9000-000000000020', 'c2130008-2b00-4e00-9000-000000000008', (select id from level), 'puzzle', 8, 'La déviation', 'Deflection', 'Dévier une pièce de sa fonction défensive afin de rendre possible une prise, un mat ou une infiltration.', 'Deflect a piece from its defensive duty so that a capture, checkmate or invasion becomes possible.', 'Quelle pièce défend la cible, et puis-je l’obliger à quitter cette case ?', 'Which piece defends the target, and can I force it away from that square?', 'La déviation ne détruit pas le défenseur : elle l’attire ailleurs, souvent vers une prise ou une réponse forcée, puis la cible initiale devient vulnérable.', 'Deflection does not destroy the defender: it lures it elsewhere, often toward a capture or forced reply, then the original target becomes vulnerable.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130021-2b00-4e00-9000-000000000021', 'c2130009-2b00-4e00-9000-000000000009', (select id from level), 'puzzle', 9, 'L’attraction', 'The decoy', 'Attirer le roi ou une pièce importante sur une case où elle devient exposée à une prise, un échec ou un motif de mat.', 'Lure the king or an important piece onto a square where it becomes exposed to a capture, check or mating pattern.', 'Sur quelle case l’adversaire serait-il obligé de venir ?', 'Which square would the opponent be forced to occupy?', 'L’attraction force une pièce à venir sur une case précise ; cette nouvelle position la rend vulnérable ou permet une combinaison.', 'A decoy forces a piece onto a precise square; its new position makes it vulnerable or enables a combination.', '7k/8/8/8/8/8/3Q4/4K3 w - - 0 1', 'Dh6'),
('d2130022-2b00-4e00-9000-000000000022', 'c2130010-2b00-4e00-9000-000000000010', (select id from level), 'puzzle', 10, 'La surcharge', 'The overload', 'Exploiter une pièce surchargée qui protège deux cibles ou remplit deux fonctions incompatibles.', 'Exploit an overloaded piece that protects two targets or performs two incompatible functions.', 'Quel défenseur est obligé de garder plusieurs choses en même temps ?', 'Which defender is forced to guard several things at once?', 'La surcharge apparaît lorsqu’un défenseur unique est responsable de deux tâches. Une attaque précise lui fait abandonner l’une d’elles.', 'Overload appears when one defender is responsible for two tasks. A precise attack makes it abandon one of them.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130023-2b00-4e00-9000-000000000023', 'c2130011-2b00-4e00-9000-000000000011', (select id from level), 'puzzle', 11, 'L’élimination du défenseur', 'Removing the defender', 'Éliminer le défenseur principal avant de capturer la cible ou de déclencher un autre motif tactique.', 'Remove the main defender before capturing the target or triggering another tactical pattern.', 'Quelle pièce protège la cible, et puis-je l’échanger ou la capturer avec gain ?', 'Which piece protects the target, and can I exchange or capture it profitably?', 'L’élimination du défenseur simplifie le réseau adverse : après la suppression de la pièce clé, une cible devient clouée, fourchable ou directement prenable.', 'Removing the defender simplifies the enemy network: after the key piece is removed, a target becomes pinned, forkable or directly capturable.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130024-2b00-4e00-9000-000000000024', 'c2130012-2b00-4e00-9000-000000000012', (select id from level), 'puzzle', 12, 'L’interférence', 'Interference', 'Interrompre une ligne de défense ou d’attaque pour empêcher une coordination et rendre une cible vulnérable.', 'Interrupt a defensive or attacking line to break coordination and expose a target.', 'Quelle pièce dépend d’une ligne ouverte, et où puis-je placer un obstacle ?', 'Which piece depends on an open line, and where can I place an obstacle?', 'L’interférence place une pièce sur une case intermédiaire qui coupe la communication entre deux pièces adverses.', 'Interference places a piece on an intermediate square that cuts communication between two enemy pieces.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', 'Fd2'),
('d2130025-2b00-4e00-9000-000000000025', 'c2130013-2b00-4e00-9000-000000000013', (select id from level), 'puzzle', 13, 'Le rayon X', 'The X-ray', 'Lire les attaques indirectes exercées à travers une pièce ou une case, et exploiter la pression qui apparaît après un déplacement ou un échange.', 'Read indirect attacks through a piece or square, and exploit the pressure that appears after a move or exchange.', 'Quelle pièce est alignée derrière la cible visible ?', 'Which piece is aligned behind the visible target?', 'Le rayon X est une pression indirecte : la pièce arrière influence une ligne même si la première pièce bloque encore le contact.', 'An X-ray is indirect pressure: the rear piece influences a line even while the front piece still blocks direct contact.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', 'Ta8+'),
('d2130026-2b00-4e00-9000-000000000026', 'c2130014-2b00-4e00-9000-000000000014', (select id from level), 'puzzle', 14, 'Le sacrifice', 'The sacrifice', 'Évaluer un sacrifice par sa compensation concrète : mat, gain matériel ultérieur, développement, lignes ouvertes ou initiative durable.', 'Evaluate a sacrifice through concrete compensation: mate, later material gain, open lines, development or lasting initiative.', 'Qu’est-ce que j’obtiens exactement en échange du matériel ?', 'What exactly do I get in exchange for the material?', 'Un sacrifice n’est pas un coup romantique : il est correct lorsque le gain de temps, de lignes ou de sécurité crée une compensation vérifiable.', 'A sacrifice is not a romantic move: it is sound when time, lines or king safety create verifiable compensation.', '6k1/8/8/8/8/8/3B4/4K3 w - - 0 1', 'Fh6'),
('d2130027-2b00-4e00-9000-000000000027', 'c2130015-2b00-4e00-9000-000000000015', (select id from level), 'calculation', 15, 'Le zwischenzug', 'The zwischenzug', 'Insérer un échec, une prise ou une menace avant la recapture attendue pour améliorer le résultat de l’échange.', 'Insert a check, capture or threat before the expected recapture to improve the exchange result.', 'Avant de reprendre, ai-je un échec ou une prise plus forte ?', 'Before recapturing, do I have a stronger check or capture?', 'Le coup intermédiaire exploite le fait que l’adversaire s’attend à une recapture immédiate. Il gagne un tempo avant de revenir au matériel.', 'The intermediate move exploits the opponent’s expectation of an immediate recapture. It gains a tempo before returning to the material.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130028-2b00-4e00-9000-000000000028', 'c2130016-2b00-4e00-9000-000000000016', (select id from level), 'puzzle', 16, 'La défense par contre-attaque', 'Counterattack defense', 'Répondre à une menace forte par une contre-menace forcing plutôt que subir une défense passive.', 'Answer a strong threat with a forcing counter-threat instead of passive defense.', 'Puis-je donner échec ou attaquer une cible plus importante ?', 'Can I give check or attack a more important target?', 'La défense active ne nie pas le danger : elle oblige l’adversaire à répondre à un problème plus urgent et gagne parfois le temps de sauver sa position.', 'Active defense does not deny the danger: it forces the opponent to answer a more urgent problem and may win time to save the position.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130029-2b00-4e00-9000-000000000029', 'c2130017-2b00-4e00-9000-000000000017', (select id from level), 'puzzle', 17, 'La menace directe', 'The direct threat', 'Identifier une menace directe qui attaque immédiatement une pièce, une case critique ou un objectif concret.', 'Identify a direct threat that immediately attacks a piece, critical square or concrete objective.', 'Que perdrai-je si je joue un coup tranquille ?', 'What will I lose if I play a quiet move?', 'Une menace directe est visible et proche : si elle n’est pas traitée, l’adversaire gagne quelque chose au prochain coup.', 'A direct threat is visible and near: if ignored, the opponent wins something on the next move.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130030-2b00-4e00-9000-000000000030', 'c2130018-2b00-4e00-9000-000000000018', (select id from level), 'puzzle', 18, 'La menace double', 'The double threat', 'Distinguer une menace double d’une attaque double et trouver une réponse qui neutralise les deux conséquences.', 'Distinguish a double threat from a double attack and find a reply that neutralizes both consequences.', 'Le coup adverse attaque-t-il deux cibles ou prépare-t-il deux résultats différents ?', 'Does the opponent’s move attack two targets or prepare two different results?', 'Une menace double décrit les conséquences promises par un coup, même si aucune pièce n’est encore attaquée directement.', 'A double threat describes the consequences promised by a move, even when no piece is directly attacked yet.', '4k3/8/8/8/8/8/3r4/3QK3 w - - 0 1', 'Dxd2'),
('d2130031-2b00-4e00-9000-000000000031', 'c2130019-2b00-4e00-9000-000000000019', (select id from level), 'puzzle', 19, 'La menace de mat', 'The mating threat', 'Reconnaître une menace de mat, calculer les cases critiques et choisir une défense qui retire réellement le danger.', 'Recognize a mating threat, calculate critical squares and choose a defense that truly removes the danger.', 'Quelle est la case de mat et quelles pièces la contrôlent ?', 'What is the mating square and which pieces control it?', 'Une menace de mat exige une réponse prioritaire. Il faut identifier la case, les lignes d’attaque et les trois familles de défense : fuir, prendre, interposer.', 'A mating threat demands priority. Identify the square, attacking lines and three defense families: move, capture, block.', '7k/5Q2/6K1/8/8/8/8/8 w - - 0 1', 'Dg7#'),
('d2130032-2b00-4e00-9000-000000000032', 'c2130020-2b00-4e00-9000-000000000020', (select id from level), 'puzzle', 20, 'La menace positionnelle', 'The positional threat', 'Comprendre une menace positionnelle : améliorer une pièce, gagner une case, créer une faiblesse ou préparer une rupture durable.', 'Understand a positional threat: improve a piece, gain a square, create a weakness or prepare a lasting break.', 'Que deviendra la position si je laisse ce plan se réaliser ?', 'What will the position become if I let this plan happen?', 'Une menace positionnelle n’est pas forcément immédiate, mais elle modifie durablement la structure, l’activité ou les cases fortes.', 'A positional threat is not necessarily immediate, but it permanently changes structure, activity or strong squares.', '4k3/8/8/8/8/8/1N6/4K3 w - - 0 1', 'Cc4'),
('d2130033-2b00-4e00-9000-000000000033', 'c2130021-2b00-4e00-9000-000000000021', (select id from level), 'puzzle', 21, 'La menace tactique', 'The tactical threat', 'Repérer une menace tactique : une combinaison concrète de coups forcing qui gagne du matériel, donne mat ou transforme la position.', 'Spot a tactical threat: a concrete combination of forcing moves that wins material, checkmates or transforms the position.', 'Quel motif se prépare si je ne change pas la géométrie ?', 'Which pattern is being prepared if I do not change the geometry?', 'La menace tactique repose sur une séquence calculable et souvent courte. Elle se distingue d’un simple plan par l’existence d’une conséquence concrète.', 'A tactical threat relies on a calculable and often short sequence. It differs from a simple plan because it has a concrete consequence.', 'k7/8/2r5/8/2N5/8/8/4K3 w - - 0 1', 'Ne5'),
('d2130034-2b00-4e00-9000-000000000034', 'c2130022-2b00-4e00-9000-000000000022', (select id from level), 'calculation', 22, 'La menace latente', 'The latent threat', 'Détecter une menace latente : une ressource cachée dans la position qui devient active après un changement de ligne, de défense ou de structure.', 'Detect a latent threat: a hidden resource in the position that becomes active after a change of line, defense or structure.', 'Quelle ressource est déjà présente mais attend une condition pour apparaître ?', 'Which resource is already present but waiting for a condition to appear?', 'Une menace latente n’est pas toujours annoncée par une attaque immédiate. Elle repose sur une tension, une batterie, une promotion ou une faiblesse qui peut se révéler.', 'A latent threat is not always announced by an immediate attack. It relies on tension, a battery, promotion or a weakness that may be revealed.', '4k3/8/8/8/8/8/8/R3B1K1 w - - 0 1', 'Fg3')
on conflict (id) do update set
  lesson_id = excluded.lesson_id,
  level_id = excluded.level_id,
  kind = excluded.kind,
  sort_order = excluded.sort_order,
  title_fr = excluded.title_fr,
  title_en = excluded.title_en,
  goal_fr = excluded.goal_fr,
  goal_en = excluded.goal_en,
  prompt_fr = excluded.prompt_fr,
  prompt_en = excluded.prompt_en,
  solution_fr = excluded.solution_fr,
  solution_en = excluded.solution_en,
  position_fen = excluded.position_fen,
  expected_san = excluded.expected_san;

commit;
